      due: '2026-09-18', desc: '乘务员报告 12 排 ABC 三个座椅靠背无法调节，影响旅客舒适度。',
      steps: [
        ['检查座椅靠背调节钢索及作动机构', 'AMM 25-21-00', 0],
        ['视情更换调节作动筒', 'AMM 25-21-00', 0],
        ['功能测试靠背调节 10 个循环', 'AMM 25-21-00', 0],
      ],
    },
    {
      card_no: 'WC-2026-0904', aircraft: 'B-7890', title: '左主轮刹车组件更换',
