          onChange={(e) => setRemarks(e.target.value)} />
      </div>
      <div className="modal-actions">
        <button className="btn" onClick={onClose}>取消</button>
        <button className="btn btn-primary" disabled={!authorized} onClick={() => onSubmit(remarks)}>确认放行</button>
      </div>
    </Modal>
  );
}

